const page = await browser.getPage("opus-mail-final");
const errs = [];
page.on("console", m => { if (m.type() === "error") errs.push(m.text()); });
page.on("pageerror", e => errs.push(String(e)));
await page.goto("http://localhost:9231/", { waitUntil: "networkidle" });
await page.waitForSelector("[data-thread]", { timeout: 10000 });
const info = await page.evaluate(() => ({
  title: document.title,
  h1: [...document.querySelectorAll("h1")].map(h => h.textContent.trim()),
  rows: document.querySelectorAll("[data-thread]").length,
}));
console.log(JSON.stringify(info));
await page.click("[data-thread]");
await page.waitForTimeout(600);
console.log("url after open:", page.url());
console.log("errors:", JSON.stringify(errs));
EOF

